internal sealed class RecoveryBuilderBudgetFixture : IDisposable
{
    internal required PdfPageLayout[] Pages { get; init; }
    internal required RecoveryRaster[] Rasters { get; init; }
    internal required Func<RecoveryBox, bool>[] Scanners { get; init; }
    internal required JsonDocument Original { get; init; }
    internal static RecoveryBuilderBudgetFixture Load(CancellationToken token = default)
    {
        using var packed = new MemoryStream(Convert.FromBase64String(Data));
        using var gzip = new GZipStream(packed, CompressionMode.Decompress);
        using var expanded = new MemoryStream(); gzip.CopyTo(expanded); var bytes = expanded.ToArray();
        if (Convert.ToHexStringLower(SHA256.HashData(bytes)) != "824cffd0b28fce2a640bd7a6a56b9b7c847c8e9bfc18f50e38ca53e910d475ba")
            throw new InvalidDataException("Fictional original source fixture changed.");
        var original = JsonDocument.Parse(bytes); var layouts = new List<PdfPageLayout>();
        var rasters = new List<RecoveryRaster>(); var scans = new List<Func<RecoveryBox,bool>>();
        foreach (var page in original.RootElement.GetProperty("pages").EnumerateArray())
        {
            var layout = JsonSerializer.Deserialize<PdfPageLayout>(page.GetProperty("layout"))!;
            using var source = new MemoryStream(Convert.FromBase64String(page.GetProperty("bgraGzip").GetString()!));
            using var pixelsGzip = new GZipStream(source, CompressionMode.Decompress);
            using var pixels = new MemoryStream(); pixelsGzip.CopyTo(pixels); var bgra = pixels.ToArray();
            if (bgra.Length != checked(layout.Width * layout.Height * 4) ||
                Convert.ToHexStringLower(SHA256.HashData(bgra)) != page.GetProperty("pixelSha256").GetString())
                throw new InvalidDataException("Original fictional pixel source changed.");
            var raster = new RecoveryRaster((int)layout.Width, (int)layout.Height, bgra);
            if (!layout.Lines.SequenceEqual(raster.Rules(token))) throw new InvalidDataException("Original raster rule extraction changed.");
            layouts.Add(layout); rasters.Add(raster); scans.Add(raster.InkFreeScanner(raster.RuleMask(layout.Lines, token), token));
        }
        return new() { Pages = layouts.ToArray(), Rasters = rasters.ToArray(), Scanners = scans.ToArray(), Original = original };
    }
